const body = $json.body || $json;
const data = body.data || {};
const key = data.key || {};
const messageId = key.id || data.id || body.id;
const fromMe = key.fromMe || body.fromMe;
const remoteJid = key.remoteJid || data.remoteJid || body.remoteJid || '';
const pushName = data.pushName || body.pushName || 'عميل الصالون';

if (fromMe) {
  return [];
}

let cleanPhone = body.senderPhone || data.senderPhone || '';
if (!cleanPhone) {
  const candidate = key.remoteJidAlt || key.participant || data.participant || remoteJid;
  cleanPhone = candidate.replace('@s.whatsapp.net', '').replace('@c.us', '').replace('@lid', '').replace(/[^0-9]/g, '');
  if (cleanPhone.startsWith('20') && cleanPhone.length === 12) {
    cleanPhone = '0' + cleanPhone.substring(2);
  }
}

// If cleanPhone is a LID (not starting with 01 or length != 11), clear it so AI asks for phone
if (!cleanPhone.startsWith('01') || cleanPhone.length !== 11) {
  cleanPhone = '';
}

const message = data.message || body.message || {};
const isImage = Boolean(message.imageMessage || body.isImage || body.imageUrl || data.imageUrl);
const imageUrl = body.imageUrl || data.imageUrl || data.mediaUrl || body.mediaUrl || null;

const textMessage = message.conversation || 
                    message.extendedTextMessage?.text || 
                    message.imageMessage?.caption || 
                    message.documentMessage?.caption || 
                    body.text || '';

if (!textMessage.trim() && !isImage) {
  return [];
}

const staticData = $getWorkflowStaticData('global');
staticData.seenTextKeys = staticData.seenTextKeys || {};
staticData.lastImageTime = staticData.lastImageTime || {};

const now = Date.now();
const textKey = (textMessage || 'img_placeholder').trim().toLowerCase();

if (isImage) {
  staticData.lastImageTime[cleanPhone || remoteJid] = now;
} else if (staticData.lastImageTime[cleanPhone || remoteJid] && (now - staticData.lastImageTime[cleanPhone || remoteJid] < 8000)) {
  return [];
}

if (textKey && staticData.seenTextKeys[textKey]) {
  const lastTime = staticData.seenTextKeys[textKey];
  if (now - lastTime < 6000) {
    return [];
  }
}
if (textKey) {
  staticData.seenTextKeys[textKey] = now;
}

return [{
  json: {
    messageId: messageId || textKey,
    remoteJid,
    phone: cleanPhone || remoteJid.replace('@s.whatsapp.net', '').replace('@lid', ''),
    realPhone: cleanPhone,
    pushName,
    chatInput: textMessage,
    text: textMessage,
    input: textMessage,
    isImage,
    imageUrl: imageUrl,
    mediaUrl: imageUrl,
    rawMessage: message,
    instance: body.instance || 'default',
    timestamp: new Date().toISOString()
  }
}];
